def calculate_fx_quote(usd_amount, trm_spot):
    spread_pct = 0.015 if usd_amount < 1000 else (0.010 if usd_amount <= 10000 else 0.006)
    effective_rate = trm_spot * (1 + spread_pct)
    cop_total = round(usd_amount * effective_rate, 2)
    return {'effective_rate': effective_rate, 'cop_total': cop_total}
